function pacFundir(cpf){if(!pacPodeUnificar()){toast('Seu perfil não tem a permissão de unificar pacientes','warn');return}const p=PACIENTES.find(x=>x.cpf===cpf)||PACIENTES[0],n=ATENDS.filter(a=>a.n===p.n).length;openModal(`${mh('Unificar cadastros')}<div class="mb"><p style="font-size:14px">CPF repetido não entra no cadastro. Aqui se junta um cadastro sem CPF ao cadastro da mesma pessoa: o que fica recebe todo o histórico do outro; nada é apagado.</p><div class="at-list"><label class="at-row check"><input type="radio" name="fd" checked><div class="grow">${esc(p.n)} · <span class="mono">${cpfMask(p.cpf)}</span> · ${dmy(p.dn)}<small>${n} ${n===1?'atendimento':'atendimentos'} · fica</small></div></label><label class="at-row check"><input type="radio" name="fd"><div class="grow">${esc(p.n.split(' ').slice(0,2).join(' '))} · sem CPF · ${dmy(p.dn)}<small>1 atendimento de 2023 · será unificado</small></div></label></div><div class="field"><label>Senha do gestor <span class="req">*</span></label><input class="in" type="password" autocomplete="new-password" placeholder="No protótipo, qualquer senha serve"></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();retorno('ok','Cadastros unificados','O histórico ficou num cadastro só. A unificação está na auditoria, com quem fez e quando.')">Unificar</button></div>`)}
