function agConfirma(d,h){AG_FOTO=false;let nome='Paciente marcado';if(AG_PRE){const n=($('#agPreN')||{}).value||'',t=($('#agPreT')||{}).value||'';if(!n.trim()||t.replace(/\D/g,'').length<10){toast('Pré-cadastro: informe nome e telefone','warn');return}nome=n.trim().split(' ')[0]+' '+(n.trim().split(' ')[1]||'').slice(0,1)+'. (pré-cad.)'}const i=AG_DIAS.indexOf(d);if(i>=0&&h){const k=i+'-'+h;AG_MARC[AG_AGENDA][k]=nome;AG_QUEM[k]=USUARIO_AG;delete AG_LIB[AG_AGENDA+'|'+k]}closeModal();reView();retorno('ok','Horário marcado!',(AG_PRE?'Pré-cadastro com nome e telefone; os dados completam na recepção. ':'')+'Lembrete programado por WhatsApp. Se a pessoa responder não, o horário é liberado e a recepção avisada.')}
function agVer(n,d,h){const k=AG_DIAS.indexOf(d)+'-'+h;openModal(`${mh(n)}<div class="mb">${kvs([['Quando',d+' · '+h],['Agenda',AG_NOME[AG_AGENDA]],['Exame',AG_EXAME[AG_AGENDA]],['Agendado por',`<b>${agQuem(k)}</b> · ${AG_QUEM_QUANDO[k]||'22/10 14:12'} · pela recepção`],['Lembrete','enviado ontem 18:00 · respondeu "sim"'],['Preparo','jejum 8 h'],['Faltas anteriores','0']])}</div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn sec" onclick="agRemarcar('${esc(n)}','${d}','${h}')">Remarcar</button><button class="btn danger sec" onclick="agFalta('${esc(n)}','${d}','${h}')">Registrar falta</button></div>`)}
