function agMover(n,d,h,d2,h2){const k=AG_DIAS.indexOf(d)+'-'+h,i2=AG_DIAS.indexOf(d2);const nome=AG_MARC[AG_AGENDA][k]||n;delete AG_MARC[AG_AGENDA][k];AG_LIB[AG_AGENDA+'|'+k]='remarcado';if(i2>=0){AG_MARC[AG_AGENDA][i2+'-'+h2]=nome;AG_QUEM[i2+'-'+h2]=USUARIO_AG}closeModal();reView();retorno('ok','Remarcado para '+d2+' · '+h2,'O horário antigo ('+d+' · '+h+') ficou livre na agenda. Novo lembrete programado'+(i2<0?'; a semana seguinte aparece ao avançar a agenda':'')+'.')}
function agFalta(n,d,h){const k=AG_DIAS.indexOf(d)+'-'+h;delete AG_MARC[AG_AGENDA][k];AG_LIB[AG_AGENDA+'|'+k]='falta de '+n.split(' ')[0];closeModal();reView();toast('Falta registrada no cadastro de '+n+'; o horário '+d+' · '+h+' ficou livre na agenda','warn')}
function agConfig(){openModal(`${mh('Configurar agendas · Unidade 10')}<div class="mb"><div class="at-list">${[['Coleta geral','seg–sáb · 07:00–11:30 · encaixe 15 min · 1 por horário'],['Infantil','seg, qua, sex · 08:00–10:00 · encaixe 20 min · 1 por horário'],['Domiciliar','seg–sex · janelas 07–09, 09–11, 11–13, 14–16 · até 4 por janela']].map(([a,b])=>`<div class="at-row"><div class="grow">${a}<small>${b}</small></div><button class="btn sm ghost" onclick="toast('Edição da agenda ${a}')">Editar</button></div>`).join('')}</div><div class="switchrow"><div>Overbooking pelo gestor<small>Permite marcar acima da capacidade com registro.</small></div><label class="switch"><input type="checkbox" checked><span class="tr"></span></label></div><div class="switchrow"><div>Reserva na marcação pela internet<small>Horário fica reservado 5 min para quem está preenchendo; não bloqueia a recepção.</small></div><label class="switch"><input type="checkbox" checked><span class="tr"></span></label></div></div><div class="mf"><button class="btn" onclick="closeModal()">Pronto</button></div>`)}
REGRAS['Agenda']={aba:'Agenda',itens:[['Marcação','Cada unidade tem uma ou mais agendas, com dias, horários, duração do encaixe (padrão 15 min) e pacientes por horário (padrão 1); overbooking só pelo gestor.'],['Exames','O sistema mostra só horários em que os exames "requer agendamento" podem ser feitos, respeitando rotina e funcionamento.'],['Fluxo','Horário marcado é prioridade na fila, não bloqueio; tolerância de atraso 15 min; depois o horário é liberado.'],['Lembretes','Véspera às 18h e 2 h antes, por WhatsApp ou SMS, com o preparo; "não" libera o horário e avisa a recepção; falta sem aviso conta no cadastro.'],['Domiciliar','Por janelas (ex.: 7h–9h), até 4 por janela; marcação pede endereço pelo CEP e forma de pagamento; o gestor monta a rota.'],['Rede','O Clínicas consulta horários livres e marca pela API; o paciente marca sozinho pela área do paciente.']]};

/* ===== Coleta domiciliar (aba Coleta: rota, kit, app do coletador, volta à unidade) ===== */
const ROTA_DOM=[{n:'Cícero Romão',end:'Rua das Flores, 120 · Aldeota',jan:'07–09',ex:['K','CREA','UREIA','GLI'],sit:'colhido',h:'07:38',pag:'Pix no agendamento',jejum:true},{n:'Dona Zefa Lima',end:'Av. Santos Dumont, 2.300 ap. 801 · Aldeota',jan:'09–11',ex:['HEMO','GLI','COL'],sit:'caminho',h:'',pag:'Maquininha na casa',jejum:true},{n:'Lívia Castro (criança)',end:'Rua Ana Bilhar, 410 · Varjota',jan:'09–11',ex:['HEMO'],sit:'agendado',h:'',pag:'Pix com o coletador',prot:'10-00018293',idade:'6 anos'},{n:'Sr. Antônio B.',end:'Rua Tibúrcio Cavalcante, 88 · Meireles',jan:'09–11',ex:['PSA','CREA'],sit:'agendado',h:'',pag:'Link de pagamento (pago)',prot:'10-00018292',idade:'66 anos',acamado:true}];
ROTA_DOM.forEach(r=>{r.foto=true});
/* Nota 104: a rota segue o grau de prioridade (por lei, jejum, acamado) e depois a região. Quem já foi colhido ou está a caminho não muda de lugar. */
const domLei=r=>{const a=parseInt(r.idade)||0;return a>=80?2:a>=60?1:0};
const domCrit=r=>[...(domLei(r)===2?['Prioridade por lei (80+)']:domLei(r)?['Prioridade por lei (60+)']:[]),...(r.jejum?['Jejum']:[]),...(r.acamado?['Acamado']:[])];
const domRegiao=r=>r.end.split(' · ').pop();
const domOrdem=()=>{const fix=ROTA_DOM.filter(r=>r.sit!=='agendado'),liv=ROTA_DOM.filter(r=>r.sit==='agendado');liv.sort((a,b)=>domLei(b)-domLei(a)||(!!b.jejum-!!a.jejum)||(!!b.acamado-!!a.acamado)||domRegiao(a).localeCompare(domRegiao(b)));return [...fix,...liv]};
function domMontar(){const o=domOrdem();openModal(`${mh('Montar rota')}<div class="mb"><p class="tl" style="margin:0">Ordem pelo grau de prioridade: prioridade por lei, jejum e acamado; no empate, a região. Quem já foi colhido ou está a caminho não muda de lugar.</p>${tabela(['Ordem','Paciente','Região','Prioridade'],o.map((r,i)=>`<tr>${td('Ordem',i+1)}${td('Paciente',esc(r.n))}${td('Região',esc(domRegiao(r)))}${td('Prioridade',domCrit(r).map(c=>`<span class="badge warn">${esc(c)}</span>`).join(' ')||'<span class="tl">Sem prioridade</span>')}</tr>`),'Nenhum atendimento')}</div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="domAplicar()">Aplicar rota</button></div>`,'wide')}
function domAplicar(){const o=domOrdem();ROTA_DOM.splice(0,ROTA_DOM.length,...o);closeModal();reView();toast('Rota montada por prioridade; o coletador recebe no app')}
VIEWS.domiciliar=()=>`${pageHead('Coleta','Coleta domiciliar','Rota do dia, kit e o que o coletador vê no celular. Funciona sem internet e sincroniza quando a rede volta. Dados de exemplo.',`${rulesBtn('Coleta domiciliar')}<button class="btn sec" onclick="domKit()" ${tipAttr('Kit da rota','Lista gerada dos exames agendados: tubos por tipo, agulhas, frascos, etiquetas e gelo, com margem de 20%.')}>Kit da rota</button><button class="btn" onclick="domMontar()" ${tipAttr('Montar rota','Ordena pelo grau de prioridade (por lei, jejum e acamado) e pela região, e deixa arrastar a ordem.')}>Montar rota</button>`)}
<div class="grid">
<div class="card ill at-card">${ILL.fila}<h3>Rota de hoje · Edna ${info('Ordem arrastável. "A caminho" manda mensagem ao paciente com a previsão de chegada.')}</h3><div class="sub">4 atendimentos · Aldeota, Meireles, Varjota</div>
<div class="steps">${ROTA_DOM.map((r,i)=>`<div class="stp ${r.sit==='colhido'?'ok':r.sit==='caminho'?'cur':''}"><span class="dot2"></span><div class="st"><b>${i+1}. ${esc(r.n)}</b> <span class="badge ${r.sit==='colhido'?'ok':r.sit==='caminho'?'acc':'neutral'}" style="margin-left:6px">${{colhido:'colhido '+r.h,caminho:'a caminho',agendado:'janela '+r.jan}[r.sit]}</span><small>${esc(r.end)} · <b>${r.ex.join(', ')}</b> · ${r.pag}${domCrit(r).length?' · <b style="color:var(--warn)">'+domCrit(r).join(', ')+'</b>':''}</small></div><div class="row" style="gap:6px">${r.sit==='agendado'?`<button class="btn sm sec" onclick="domCaminho(${i})">A caminho</button>`:r.sit==='caminho'?`<button class="btn sm" onclick="domColeta('${esc(r.n)}')">Colher</button>`:''}${r.sit!=='colhido'?`<button class="btn sm ghost" onclick="modalOk('Não colhida','<p>Registra o motivo e devolve para a recepção reagendar; o paciente recebe aviso.</p><div class=\\'field\\'><label>Motivo</label><select class=\\'in\\'><option>Paciente ausente</option><option>Endereço não encontrado</option><option>Preparo não cumprido</option></select></div>','Registrar','toast(\\'Devolvido para a recepção reagendar\\',\\'warn\\')')">Não colhida</button>`:''}</div></div>`).join('')}</div>
<div class="row" style="margin-top:12px"><button class="btn sec" onclick="toast('Chegou da rota: 1 amostra lida, rota fechada, pronta para o transporte')" ${tipAttr('Chegou da rota','Na volta, lê cada tubo; fecha a rota e deixa tudo pronto para o transporte ou a bancada.')}>Chegou da rota</button></div>
${piada(19,{coletador:'Rota de 4 casas: 3 cachorros, 2 cafés oferecidos e 1 "nossa, nem senti". Dia produtivo.',gestor:'Montar a rota é fácil. Difícil é explicar ao trânsito de Fortaleza que a janela é das 9 às 11.',todos:'O app funciona sem internet. O coletador funciona sem café. Só um dos dois é verdade.'})}</div>
<div class="card at-card"><h3>Tela do coletador (celular) ${info('Versão reduzida da tela da coleta: paciente, exames, tubos, perguntas e confirmar. O pedido já vem anexado da marcação; assinatura na tela.')}</h3><div class="sub">Como aparece no app, no atendimento ${domAtual()+1}</div>
${domTela(domAtual())}
<p class="tl" style="margin-top:10px">Modo de etiqueta desta rota: impressora portátil Bluetooth. Alternativas nas configurações: pré-impressas na unidade (conferidas pelo código no app) ou escritas à mão (conferência rigorosa no recebimento).</p></div>
</div>`;
/* 04/11 (anotações 194 a 198): Colher abre a tela do coletador; etiqueta com prévia; foto pelo celular; assinatura na tela; triagem */
ROTA_DOM.forEach((r,i)=>{r.prot=r.prot||['10-00018262','10-00018291','10-00018292','10-00018293'][i];r.idade=r.idade||['71 anos','78 anos','66 anos','6 anos'][i]});
const domAtual=()=>{const c=ROTA_DOM.findIndex(r=>r.sit==='caminho');if(c>=0)return c;const a=ROTA_DOM.findIndex(r=>r.sit==='agendado');return a>=0?a:ROTA_DOM.length-1};
function domCaminho(i){const r=ROTA_DOM[i];r.sit='caminho';reView();toast('Mensagem enviada a '+r.n.split(' ')[0]+': previsão de chegada em 25 min')}
function domTela(i,emModal){const r=ROTA_DOM[i];if(!r)return '';const pf='dm'+i,t=triDe(r.prot);
 return `<div class="at-found" id="domTela${i}"><h4>${esc(r.n)} · ${r.idade}</h4><div>${exNomes(r.ex)}</div>
 <div class="field"><label>Ordem de coleta</label>${ordemColeta(r.ex,{nota:false})}</div>
 <div class="field"><label>Jejum cumprido? <span class="req">*</span></label><div class="row"><label class="check"><input type="radio" name="jj${i}" checked>Sim, 10 h</label><label class="check"><input type="radio" name="jj${i}">Não</label></div></div>
 <details ${emModal?'open':''}><summary style="cursor:pointer;font-weight:700">Triagem ${t.med||(t.cron||[]).length?'<span class="badge ok" style="margin-left:6px">preenchida</span>':'<span class="badge warn" style="margin-left:6px">a preencher</span>'}</summary><div style="margin-top:8px">${triagemCampos(pf,t)}<p class="tl">Fica no atendimento; a biomédica confere ao bipar na área técnica.</p></div></details>
 <div class="row"><button class="btn sm sec" onclick="domEtq(${i})">${I.print} Imprimir etiquetas</button><button class="btn sm sec" onclick="domFoto(${i})">Ver pedido</button><button class="btn sm sec" onclick="domAss(${i})">Assinatura${r.ass?' ✓':''}</button></div>
 <div class="row" style="gap:6px"><span class="badge ok">pedido anexado na marcação</span>${r.ass?'<span class="badge ok">assinado pelo cliente</span>':''}</div>
 <button class="btn" onclick="domConfirma(${i},${emModal?1:0})">Confirmar coleta</button></div>`}
const domCtx=i=>{const r=ROTA_DOM[i];return {n:r.n,prot:r.prot,exs:r.ex,modo:'Impressora portátil Bluetooth',tri:Object.assign(triDe(r.prot),domTriLer(i))}};
function domTriLer(i){const pf='dm'+i;return document.getElementById(pf+'Med')?triagemLer(pf):{}}
function domEtq(i){const o=domCtx(i);Object.assign(triDe(o.prot),o.tri);sobreModal(()=>etiquetaPrev(o),'Voltar à coleta')}
function domRedesenha(i){const el=document.getElementById('domTela'+i);if(el)el.outerHTML=domTela(i,!!el.closest('#modal'))}
function domFoto(i){const r=ROTA_DOM[i];Object.assign(triDe(r.prot),domTriLer(i));sobreModal(()=>openModal(`${mh('Pedido médico · '+esc(r.n))}<div class="mb"><div class="empty"><h4>Foto do pedido anexada na marcação</h4><p>Exames: ${esc(exNomes(r.ex))}. Imagem de exemplo no protótipo.</p></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button></div>`),'Voltar à coleta')}
function domAss(i){const r=ROTA_DOM[i];Object.assign(triDe(r.prot),domTriLer(i));const g=modalGuarda();assinaturaModal(r.n,()=>{r.ass=true;if(g)modalRestaura(g);domRedesenha(i)});modalVolta(g,'Voltar à coleta')}
function domConfirma(i,emModal){const r=ROTA_DOM[i];Object.assign(triDe(r.prot),domTriLer(i));if(!r.ass){toast('Falta a assinatura do cliente: toque em Assinatura','warn');return}
 r.sit='colhido';r.h=hhmm(new Date());const prox=ROTA_DOM.find(x=>x.sit==='agendado');if(emModal)closeModal();reView();
 retorno('ok','Coleta registrada',`${tubosDe(r.ex).length} amostra(s) de ${esc(r.n.split(' ')[0])} em C (colhido) às ${r.h}, com triagem e assinatura. Sincroniza quando a rede voltar.${prox?' Próximo: '+esc(prox.n)+'.':''}`)}
function domColeta(n){const i=ROTA_DOM.findIndex(r=>r.n===n);if(i<0)return;openModal(`${mh('Coleta em casa · '+esc(n))}<div class="mb"><p class="tl">Tela do coletador no celular. Sem internet, tudo fica no aparelho e sincroniza depois.</p>${domTela(i,true)}</div>`)}
function domKit(){openModal(`${mh('Kit da rota de hoje')}<div class="mb"><p style="font-size:14px;color:var(--fg2)">Gerado dos exames agendados, com margem de 20%. Confira e saia.</p><div class="at-list">${[['Tubo soro (tampa vermelha)','6'],['Tubo EDTA (tampa roxa)','4'],['Tubo fluoreto (tampa cinza)','3'],['Agulhas e adaptadores','12'],['Etiquetas pré-impressas','não (modo Bluetooth)'],['Gelo e caixa térmica','sim (PSA)']].map(([a,b])=>`<label class="at-row check"><input type="checkbox" checked><div class="grow">${a}</div><b>${b}</b></label>`).join('')}</div></div><div class="mf"><button class="btn" onclick="closeModal();toast('Kit conferido; rota liberada')">Conferido</button></div>`)}
GUIDES.domiciliar=['O gestor monta a rota por região; o coletador vê tudo no celular, com endereço, exames e preparo.','Antes de sair, confira o kit gerado dos exames agendados.','Na casa: identifica, pergunta o preparo, imprime as etiquetas e confirma. Sem internet, tudo fica no celular e sincroniza depois.'];
REGRAS['Coleta domiciliar']={aba:'Coleta, domiciliar e app do coletador',itens:[['Rota','Montar rota ordena pelo grau de prioridade: prioridade por lei, jejum e pacientes acamados; no empate, a região.'],['App','Rota do dia e tela reduzida da coleta; funciona sem internet; pedido anexado na marcação e assinatura na tela; login por biometria; aparelho vinculado à unidade.'],['Etiquetas','Três modos por unidade ou agenda: impressora Bluetooth; pré-impressas conferidas pelo código; à mão, com conferência rigorosa no recebimento.'],['Kit','Gerado dos exames agendados com margem de 20%; coletador confere e sai.'],['Volta','"Chegou da rota" lê os tubos, fecha a rota e deixa tudo pronto para o transporte. Não colhida fica com motivo e volta para a recepção reagendar.'],['Pagamento','No agendamento (Pix, link) ou na casa (maquininha, Pix); sem internet fica "a confirmar" e entra no caixa na sincronização.']]};

