function trLista(){const f=FILTROS.tr||{};return REMESSAS.filter(r=>perDentro('tr',r.d)&&(!f.unidade||r.unid==f.unidade)&&(!f.situacao||r.sit===f.situacao)&&(!f.urgencia||(f.urgencia==='urg')===!!r.urg)&&(!f.tipo||r.tipo===f.tipo)&&(!f.mot||r.mot===f.mot))}
