const transTubos=r=>r.cods?r.cods.map(c=>AM(c)||{cod:c,tipo:r.tipo,banc:'a identificar'}):AMOSTRAS.filter(a=>a.unid===r.unid&&trTipoDe(a)===r.tipo);
/* Nota 203: os indicadores abrem as remessas daquela situação */
function transVerSit(s){listaDrawer(SIT_REM[s][0],trLista().filter(r=>r.sit===s).map(r=>`<a href="#" style="display:block;color:inherit;text-decoration:none" onclick="event.preventDefault();transFicha('${r.id}')"><span class="mono">${r.id}</span> · <b>${esc(r.tipo)}</b><small style="display:block">${esc(unidNome(r.unid).split(' · ')[0])} · ${r.tubos} tubos · ${r.saida?'saiu '+r.saida:'não saiu'}${r.cheg?' · chegou '+r.cheg:''} · ${r.tempS||'pendente'} → ${r.tempC||'pendente'}</small></a>`),'Clique na remessa para ver os tubos e o rastreio.')}
function transFicha(id){const r=REMESSAS.find(x=>x.id===id),tb=transTubos(r);openDrawer('Remessa '+id,`${kvs([['Posto',unidNome(r.unid)],['Tipo de amostra',r.tipo],['Situação',SIT_REM[r.sit][0]],['Saiu às',r.saida||'não saiu'],['Tubos e exames',r.tubos+' tubos · '+r.ex+' exames'],['Previsão',r.prev],['Quem enviou',r.env||'ainda não enviado'],['Temp. de saída',r.tempS||'pendente'],['Temp. de chegada',r.tempC||'pendente'],['Motorista',r.mot||'a definir'],r.cobrado&&['Cobrança','posto avisado às '+r.cobrado]])}<div class="row" style="gap:6px;margin:10px 0"><button class="btn sm ghost" onclick="transEtiqueta('${id}')">${I.print} Etiqueta do lote</button><button class="btn sm ghost" onclick="transRomaneio('${id}')">${I.print} Romaneio</button></div><h4>Rastreio</h4><div class="steps"><div class="stp ${r.saida?'ok':'cur'}"><span class="dot2"></span><div class="st">Fechada no posto<small>${r.saida?r.saida+' · romaneio impresso':'pendente'}</small></div></div><div class="stp ${r.sit==='caminho'?'cur':r.sit==='chegou'?'ok':''}"><span class="dot2"></span><div class="st">Retirada bipada pelo motorista<small>${r.mot==='Edson (app)'&&r.saida?r.saida+' · Edson · localização gravada':r.saida?'posto sem app: só bipagem na chegada':'pendente'}</small></div></div><div class="stp ${r.sit==='chegou'?'ok':''}"><span class="dot2"></span><div class="st">Chegou na matriz<small>${r.cheg?r.cheg+' · caixa bipada · '+r.tubos+' tubos':'pendente'}</small></div></div></div><h4>Tubos</h4><div class="at-list">${tb.map(a=>`<div class="at-row"><div class="grow"><span class="mono">${a.cod}</span><small>${a.tipo} · ${a.banc}${a.falta?' · <b style=\"color:var(--err)\">faltante</b>':''}</small></div></div>`).join('')||'<p class="tl">Nenhum tubo de exemplo neste lote.</p>'}</div>${tb.length&&tb.length<r.tubos?`<p class="tl">Mostrando ${tb.length} de ${r.tubos} tubos.</p>`:''}`)}
function transEtiqueta(id){const r=REMESSAS.find(x=>x.id===id);etqCaixa({titulo:'Lote '+id,cod:id,num:id,linhas:['Tipo de amostra: '+r.tipo,unidNome(r.unid)+' para Central',r.tubos+' tubos · '+r.ex+' exames',r.saida?'Saída '+r.saida+(r.tempS?' · '+r.tempS:''):'Saída a definir'],saida:'Impressora do posto '+r.unid})}
function transNova(){transNovaAbre()}
/* 04/11 (anotação 200): amostras colhidas que não estão em nenhum lote de envio */
const FALT_SVG='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 3h6M10 3v11.5a2 2 0 0 0 4 0V3"/><path d="M4 4l16 16"/></svg>';
const TRANS_FALT=[{cod:'14-00004503-04-01',n:'Joana Darc Pereira',ex:'Urina tipo 1',tipo:'Urina',h:'07:25',unid:14},{cod:'14-00004504-01-01',n:'Antônio Carlos Bezerra',ex:'Glicose, Creatinina',tipo:'Soro',h:'08:02',unid:14},{cod:'14-00004505-03-01',n:'Maria das Dores Lima',ex:'Hemograma completo',tipo:'Sangue total',h:'08:14',unid:14}];
const transFaltDe=r=>r.sit==='aberta'?TRANS_FALT.filter(f=>f.unid===r.unid&&f.tipo===r.tipo&&!f.inc):[];
function transFaltantes(unid){const l=TRANS_FALT.filter(f=>!f.inc&&(!unid||f.unid===unid));listaDrawer('Amostras faltantes no lote',l.map(f=>`<span style="display:flex;gap:8px;align-items:center"><span class="falt-ic">${FALT_SVG}</span><span class="mono">${f.cod}</span></span><small style="display:block;color:var(--fg2)">${esc(f.n)} · ${esc(f.ex)} · ${f.tipo} · colhida às ${f.h} · ${esc(unidNome(f.unid))}</small><button class="btn sm sec" style="margin-top:6px" onclick="transIncluir('${f.cod}')">Incluir no lote aberto</button>`),l.length?'Colhidas hoje e ainda fora de qualquer remessa. Inclua no lote aberto do mesmo tipo de amostra antes de fechar.':'Nenhuma amostra colhida fora do lote.')}
function transIncluir(cod){const f=TRANS_FALT.find(x=>x.cod===cod);if(!f)return;const r=REMESSAS.find(x=>x.unid===f.unid&&x.sit==='aberta'&&x.tipo===f.tipo);if(!r){toast(`Sem lote aberto de ${f.tipo} neste posto: crie uma nova remessa desse tipo`,'warn');return}f.inc=true;r.tubos++;closeDrawer();reView();toast(`${cod} incluída no lote ${r.id}`)}
const trAgora=()=>new Date().toTimeString().slice(0,5);
const trPrev=()=>new Date(Date.now()+36e5).toTimeString().slice(0,5);
/* Lê a temperatura digitada (ex.: 4,2); inválida devolve vazio */
function trTemp(sel){const m=String($(sel).value).trim().match(/^-?\d{1,2}([.,]\d+)?/);return m?m[0].replace('.',',')+' °C':''}
let TR_NOVA=[];
function trFaltAviso(){const el=$('#trFalt');if(!el)return;const t=$('#trTipo').value,l=TRANS_FALT.filter(f=>!f.inc&&f.unid===14&&f.tipo===t&&!TR_NOVA.includes(f.cod));el.innerHTML=l.length?`<div class="alert warn"><span class="falt-ic">${FALT_SVG}</span><span><b>${l.length} amostra(s) de ${t} colhida(s) hoje ainda fora do lote:</b> ${l.map(f=>f.cod).join(', ')}.</span><button class="btn sm warn" onclick="trFaltInc()">Incluir</button></div>`:''}
function trFaltInc(){const t=$('#trTipo').value;TRANS_FALT.filter(f=>!f.inc&&f.unid===14&&f.tipo===t&&!TR_NOVA.includes(f.cod)).forEach(f=>{TR_NOVA.push(f.cod);bipLog('trLog',`<span class="ok">✓</span> ${f.cod} · ${esc(f.n)} · entrou no lote`)});trFaltAviso()}
function trBipar(c){const t=$('#trTipo').value;if(c.tipo!=='tubo'){bipLog('trLog',`<span style="color:var(--err);font-weight:800">✕</span> ${c.cod}: no lote entra tubo por tubo (14 dígitos)`);return}const a=AM(c.cod);if(a&&trTipoDe(a)!==t){bipLog('trLog',`<span style="color:var(--err);font-weight:800">✕</span> ${c.cod} é ${trTipoDe(a)}: este lote é de ${t}`);return}if(TR_NOVA.includes(c.cod)){bipLog('trLog',`<span style="color:var(--warn);font-weight:800">?</span> ${c.cod} já está no lote`);return}TR_NOVA.push(c.cod);bipLog('trLog',`<span class="ok">✓</span> ${c.cod}${a?' · '+esc(a.n)+' · '+a.ex.join(', '):' · sem pedido: confira'} · entrou no lote`);trFaltAviso()}
function transNovaAbre(){TR_NOVA=[];BIP_LOG.trLog=[];openModal(`${mh('Nova remessa · Posto 14')}<div class="mb"><div class="formgrid"><div class="field"><label>Tipo de amostra <span class="req">*</span> ${info('Cada lote leva um só tipo de amostra. Tubo de outro tipo é recusado na bipagem.')}</label><select class="in" id="trTipo" onchange="TR_NOVA=[];BIP_LOG.trLog=[];$('#trLog').innerHTML='';trFaltAviso()">${TR_TIPOS.map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label>Temp. de saída <span class="req">*</span></label><input class="in" id="trTempS" value="4,0 °C"></div><div class="field"><label>Motorista ou rota</label><select class="in" id="trMot"><option>Edson (app)</option><option>sem motorista com app</option></select></div></div><div class="inwrap">${LUPA}<input class="in" placeholder="Bipe cada tubo: entra no lote e o campo fica pronto para o próximo" id="trBip"></div><div class="bip-log" id="trLog"></div><div id="trFalt"></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="transNovaOk()">Fechar e imprimir romaneio</button></div>`);trFaltAviso();bipAuto($('#trBip'),trBipar)}
function transNovaOk(){if(!TR_NOVA.length){toast('Bipe ao menos um tubo','warn');return}const tempS=trTemp('#trTempS');if(!tempS){toast('Informe a temperatura de saída','warn');return}const seq=Math.max(...REMESSAS.filter(r=>r.unid===14).map(r=>+r.id.split('-')[1]))+1,id='14-'+String(seq).padStart(4,'0'),cods=[...TR_NOVA];
 cods.forEach(c=>{const f=TRANS_FALT.find(x=>x.cod===c);if(f)f.inc=true});REMESSAS.unshift({id,unid:14,tipo:$('#trTipo').value,sit:'caminho',saida:trAgora(),cheg:'',prev:trPrev(),mot:$('#trMot').value,env:nomePerfil(PERFIL),tubos:cods.length,ex:cods.reduce((s,c)=>s+(AM(c)?AM(c).ex.length:1),0),tempS,tempC:'',urg:false,cods});closeModal();reView();transRomaneio(id)}
function transFechar(id){const r=REMESSAS.find(x=>x.id===id);openModal(`${mh('Fechar lote '+id+' · '+r.tipo)}<div class="mb"><p style="font-size:14px">${r.tubos} tubos. Os tubos passam a Enviado (N) e a matriz recebe a previsão de chegada.</p><div class="formgrid"><div class="field"><label>Temp. de saída <span class="req">*</span></label><input class="in" id="trTempF" value="4,0 °C"></div><div class="field"><label>Motorista ou rota</label><select class="in" id="trMotF"><option>Edson (app)</option><option>sem motorista com app</option></select></div></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="transFecharOk('${id}')">Fechar e imprimir romaneio</button></div>`)}
function transFecharOk(id){const t=trTemp('#trTempF');if(!t){toast('Informe a temperatura de saída','warn');return}const r=REMESSAS.find(x=>x.id===id);r.tempS=t;r.mot=$('#trMotF').value;r.saida=trAgora();r.prev=trPrev();r.env=nomePerfil(PERFIL);r.sit='caminho';closeModal();reView();transRomaneio(id)}
function transChegada(id){const r=REMESSAS.find(x=>x.id===id);openModal(`${mh('Chegada do lote '+id+' · '+r.tipo)}<div class="mb"><p style="font-size:14px">Saiu às ${r.saida} com ${r.tempS||'temperatura não registrada'}.</p><div class="field"><label>Temp. de chegada <span class="req">*</span></label><input class="in" id="trTempC" placeholder="Ex.: 4,8"></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="transChegadaOk('${id}')">Registrar chegada</button></div>`)}
function transChegadaOk(id){const t=trTemp('#trTempC');if(!t){toast('Informe a temperatura de chegada','warn');return}const r=REMESSAS.find(x=>x.id===id),n=numRes(t);r.tempC=t;r.cheg=trAgora();r.sit='chegou';closeModal();reView();if(n<2||n>8)toast(`Lote ${id} chegou a ${t}, fora de 2 a 8 °C: confira no recebimento`,'warn');else toast(`Lote ${id} chegou a ${t}: vai para o recebimento`)}
function transCobrar(id){const r=REMESSAS.find(x=>x.id===id);r.cobrado=trAgora();toast('Posto '+r.unid+' avisado: lote '+id+' passou do horário sem fechar','warn')}
function transRomaneio(id){const r=REMESSAS.find(x=>x.id===id);if(!r)return;const l=transTubos(r);openModal(`${mh('Romaneio · remessa '+id)}<div class="mb"><div class="etq"><div class="eb"><b>Remessa ${id} · ${r.tipo}</b>${barcodeSvg(id)}<div>${esc(unidNome(r.unid))} para Central · ${r.tubos} tubos · ${r.ex} exames</div><div>Saída ${r.saida||'a definir'} · ${r.tempS||'temp. a registrar'} · ${esc(r.mot||'sem motorista')}</div><div class="em">${l.map(a=>a.cod).join(' · ')||'Tubos conforme bipagem'}</div></div></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn" onclick="closeModal();toast('Romaneio da remessa ${id} enviado à impressora')">${I.print} Imprimir romaneio</button></div>`)}
GUIDES.transporte=['No posto: crie um lote por tipo de amostra, bipe cada tubo, registre a temperatura de saída, feche e imprima o romaneio e a etiqueta do lote.','O motorista bipa o código da remessa ao retirar e ao entregar; a matriz vê "a caminho" com previsão e registra a temperatura de chegada.','Remessa que passa do horário sem fechar ou sem chegar vira alerta ao gestor.'];
REGRAS['Transporte']={aba:'Recebimento de amostras',itens:[['Remessa','O posto cria um lote por tipo de amostra (soro, sangue total, urina, fezes...) e bipa as amostras colhidas; tubo de outro tipo é recusado; o sistema avisa as colhidas do dia que ficaram de fora.'],['Romaneio','Ao fechar, imprime o romaneio (lista com código de barras); amostras passam a Enviado; registra quem fechou, hora, temperatura de saída e motorista ou rota. A chegada registra a temperatura de chegada. Cada lote tem etiqueta própria.'],['Motorista','Usa o app do coletador em modo transporte; bipa ao retirar e ao entregar; hora e localização gravadas. Posto sem app: bipagem só na chegada.'],['Alertas','Remessa atrasada ao passar do horário previsto sem fechar; não chegada até previsão + 60 min (configurável) vira alerta ao gestor; urgente destaca a remessa e avisa a matriz.']]};

