function rc3Html(){const f=FILTROS.rc3||{},q=semAc((f.q||'').trim());const l=AMOSTRAS.filter(a=>perDentro('rc3',undefined,'semana')&&(!q||semAc(a.cod+' '+a.prot+' '+a.n+' '+a.ex.join(' ')+' '+a.banc).includes(q))&&(!f.unidade||a.unid==f.unidade)&&(!f.bancada||a.banc===f.bancada)&&(!f.situacao||a.sit===f.situacao));
 return `${tabela(['Tubo','Paciente','Envio','Destino','Setor','Situação'],l.map(a=>`<tr>${td('Tubo',`<span class="mono">${a.cod}</span>`)}${td('Paciente',esc(a.n))}${td('Envio',unidNome(a.unid)+(a.h?' · '+a.h:''))}${td('Destino',a.apoio?a.apoio:'Central')}${td('Setor',a.banc)}${td('Situação',a.falta?'<span class="badge err">Tubo faltante</span>':a.recusa?'<span class="badge warn">Rejeitada</span>':letra(a.sit))}</tr>`),'Nenhuma amostra com estes filtros')}<div class="tfoot"><span>${l.length} de ${AMOSTRAS.length} amostras</span></div>`}
