function rcBipar(c){if(c.tipo==='protocolo'){const l=amostrasDe(c);bipLog('rcLog',l.length?`<span class="ok">✓</span> protocolo ${c.cod} · ${esc(l[0].n)} · ${l.length} tubo(s): ${l.map(a=>a.cod.slice(-5)+' '+a.banc).join(', ')}`:`<span style="color:var(--err);font-weight:800">✕</span> ${c.cod}: nenhum tubo deste protocolo nesta remessa`);return}const a=AM(c.cod);bipLog('rcLog',a?`<span class="ok">✓</span> ${c.cod} · ${esc(a.n)} · recebido → ${a.banc}${a.ex.includes('K')?' (centrifugar)':''}`:`<span style="color:var(--warn);font-weight:800">?</span> ${c.cod}: sem pedido. Entra como pendente de identificação e avisa o posto`)}
function rcBipagem(){bipAuto($('#rcBip'),rcBipar)}
{const _p=posRender;posRender=function(id){_p(id);if(id==='recebimento')rcBipagem()}}
function rcRejeitar(cod){openModal(`${mh('Rejeitar amostra')}<div class="mb"><p style="font-size:14px"><span class="mono">${cod}</span></p><div class="field"><label>Motivo <span class="req">*</span> ${info('Lista padrão da D14, editável nas configurações. A rejeição registra motivo, usuário e hora, abre recoleta e entra no indicador de amostras rejeitadas.')}</label><select class="in" id="rcMot">${MOTIVOS_REJ.map(m=>`<option>${m}</option>`).join('')}</select></div><div class="field"><label>Descrição</label><textarea class="in" id="rcDesc" placeholder="Obrigatória em Outro"></textarea></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn danger" onclick="rcRejeitarOk('${cod}')">Rejeitar</button></div>`)}
function rcRejeitarOk(cod){const m=$('#rcMot').value,d=$('#rcDesc').value.trim();if(m.startsWith('Outro')&&!d){toast('Descreva o motivo','warn');return}const a=AM(cod);a.recusa=m;a.sit='J';recCriar({cod,pac:a.n,ex:a.ex.join(', ')},m,'laboratório',d);closeModal();reView();toast('Amostra rejeitada (J): recoleta registrada em Recoletas','warn')}
