let PC_LT='';
const CL_LT_TIPO={agenda:['Agendamentos'],pre:['Pré-agendamentos'],recepcao:['Recepção'],guia:['Guias'],consulta:['Consultas','c-teal'],lab:['Exames de laboratório','c-green'],imagem:['Laudos de imagem','c-blue'],prescricao:['Prescrições','c-purple'],procedimento:['Procedimentos','c-orange'],pagamento:['Pagamentos','c-pink'],pos:['Pós-atendimento']};
function clLinhaHtml(p){rc();const ev=[...RC.hist.filter(e=>e.pac===p.n),...clLinhaDe(p.n)];const futuros=CL_AG_NOVOS.filter(a=>a.pac===p.n&&a.dia!=='hoje');futuros.forEach(a=>ev.unshift({d:'2026-11-'+(a.dia||'06/11').slice(0,2),t:'consulta',tit:'Agendado · '+a.itens.map(clProcNome).join(', '),quem:a.jornada,txt:a.dia+' às '+a.h,st:'agendado'}));
 const l=ev.sort((a,b)=>b.d.localeCompare(a.d)).filter(e=>!PC_LT||e.t===PC_LT),cpf=p.cpf;let dia='';
 return `<div class="row" style="gap:6px;margin:4px 0 10px">${chip('Tudo',!PC_LT,`PC_LT='';pacFicha('${cpf}','tempo')`)}${Object.entries(CL_LT_TIPO).filter(([k])=>ev.some(e=>e.t===k)).map(([k,[t]])=>chip(t,PC_LT===k,`PC_LT='${k}';pacFicha('${cpf}','tempo')`)).join('')}</div>
 ${l.length?`<div class="cl-tl">${l.map((e,i)=>{const d=dmy(e.d),sep=d!==dia?`<div class="day">${e.st==='hoje'||e.d==='2026-11-04'?'Hoje · '+d:d}</div>`:'';dia=d;const ix=clLinhaDe(p.n).indexOf(e);return `${sep}<div class="ev ${e.t}"><div class="eh"><b>${esc(e.tit)}</b><small>${esc(e.quem||'')}</small>${e.st?`<span class="badge ${e.st==='hoje'?'acc':'info'}" style="height:20px;font-size:11px">${e.st}</span>`:''}</div><p>${esc(e.txt||'')}</p>${e.serie?`<div class="tl" style="margin-top:6px">${esc(e.serie.n)}</div>${graficoHist(e.serie.hist,e.serie.faixa)}`:''}<div class="row" style="gap:6px;margin-top:6px">${e.laudo?`<button class="btn sm sec" onclick="clLtLaudo('${cpf}',${ix})">Ver laudo</button>`:''}${e.t==='lab'?`<button class="btn sm ghost" onclick="closeDrawer();location.hash='#laudos'">Laudo evolutivo</button>`:''}${e.t==='prescricao'?`<button class="btn sm sec" onclick="clLtReceita('${cpf}',${ix})">Ver receita</button>`:''}${e.t==='pagamento'?`<button class="btn sm ghost" onclick="toast('Recibo reimpresso (2ª via), com a nota fiscal')">Recibo</button>`:''}</div></div>`}).join('')}</div>`:'<p class="tl">Nada deste tipo na linha do tempo.</p>'}
 <p class="tl" style="margin-top:10px">Uma linha do tempo para a clínica, o laboratório, a imagem e o hospital. Quem vê cada item depende do perfil: a recepção vê agenda e pagamentos; resultados e prescrições, só quem tem a permissão. ${info('LGPD: cada abertura da ficha fica na auditoria (aba Rastreabilidade).')}</p>`}
function clLtLaudo(cpf,i){const p=PACIENTES.find(x=>x.cpf===cpf),e=clLinhaDe(p.n)[i];if(!e)return;openModal(`${mh('Laudo · '+esc(e.tit.replace(/^Laudo · /,'')))}<div class="mb"><div class="laudo" style="max-width:none;padding:16px"><b style="color:var(--fg-strong)">DeoClinic · ${e.t==='imagem'?'Imagem e ultrassom':'Cardiologia'}</b><p class="tl">${esc(p.n)} · ${dmy(e.d)}</p><h4 style="margin-top:10px">Impressão</h4><p>${esc(e.txt)}</p><p class="tl" style="margin-top:12px">Assinado eletronicamente por ${esc(e.quem)} · ICP-Brasil</p></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button>${e.t==='imagem'?`<button class="btn sec" onclick="closeModal();closeDrawer();location.hash='#imagem-worklist'">Ver imagens</button>`:''}<button class="btn" onclick="toast('Laudo enviado à impressora')">${I.print} Imprimir</button></div>`,'wide')}
function clLtReceita(cpf,i){const p=PACIENTES.find(x=>x.cpf===cpf),e=clLinhaDe(p.n)[i];if(!e)return;openModal(`${mh('Receita · '+dmy(e.d))}<div class="mb"><div class="laudo" style="max-width:none;padding:16px"><b style="color:var(--fg-strong)">${esc(e.quem)}</b><p class="tl">Paciente: ${esc(p.n)}</p><h4 style="margin-top:10px">${esc(e.tit.replace(/^Prescrição · /,''))}</h4><p>${esc(e.txt)}</p><p class="tl" style="margin-top:12px">Código de verificação K3D9-7QX2 · validar em deoclinic.com.br/receita</p></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn sec" onclick="toast('Receita reenviada por WhatsApp com o link de validação')">Reenviar</button><button class="btn" onclick="closeModal();closeDrawer();location.hash='#atendimento-medico'">Abrir no prontuário</button></div>`,'wide')}
/* ----- Atendimentos de hoje: consultas, imagem e procedimentos ao lado dos protocolos do laboratório ----- */
function clAtRows(q){const l=clAgendaHoje().filter(a=>!['Coleta','Domiciliar'].includes(a.tipo)&&(!q||semAc(a.pac).includes(q)));
 return l.map(a=>`<tr style="cursor:pointer" onclick="clAgVer('${a.ref}')" ${tipAttr(a.pac,'Consulta, exame de imagem ou procedimento de hoje. Clique para ver preparo, pagamento e guia.')}><td data-l="Protocolo"><span class="mono">CL-${String(18400+(+a.ref.slice(1))+(a.ref[0]==='c'?0:a.ref[0]==='e'?50:80)).padStart(5,'0')}</span></td><td data-l="Paciente"><div class="two">${esc(a.pac)}<small>${esc(a.itens.map(clProcNome).join(', '))}</small></div></td><td data-l="Origem"><span class="badge neutral">${a.jornada?'Jornada':'Agenda'}</span> <span class="badge ${a.tipo==='Imagem'?'info':a.tipo==='Procedimento'?'warn':'acc'}">${(CL_TIPOS[a.tipo]||[a.tipo])[0]}</span></td><td data-l="Situação"><div class="two"><span>${a.sit}</span><small>${a.pago?'pago':'a receber'} · ${esc(a.conv)}</small></div></td></tr>`).join('')}

/* ---------- 04/11 · Onda 2 · Plano e pacote no Novo atendimento ----------
   Quando o paciente (titular ou dependente) tem plano ou pacote, a recepção vê a elegibilidade logo no cadastro e o pedido
   aplica sozinho a cobertura, o desconto ou o saldo do pacote, item a item, no detalhamento do preço. Ninguém digita desconto de plano.
   Regras e dados em dados-clinica.js (PL_), tela em Planos e pacotes. */
function naPlContratos(){if(!NA||NA.modo!=='atendimento'||typeof plContratosDe!=='function')return [];return plContratosDe(NA.semCpf?'':NA.cpf,(NA.pac||{}).n)}
function naPlRecalc(){if(!NA||NA.modo!=='atendimento'||typeof plAplicar!=='function')return;
 const ks=naPlContratos().slice().sort((a,b)=>(a.tipo==='pacote'?0:1)-(b.tipo==='pacote'?0:1)),usar=ks.length&&NA.tipo==='particular'&&!NA.plOff,extra={};
 NA.ex.forEach(x=>{if(x.p0===undefined)x.p0=x.p;x.pl=null;let p=x.p0;
  if(usar){let best=null;ks.forEach(k=>{const r=plAplicar(k,NA.pac.n,x.c,x.p0,extra[k.id]||{});if(!best||r.final<best.final||(!best.via&&r.via))best={...r,k:k.id,kn:plRef(k).n}});
   if(best){x.pl=best;p=best.final;if(best.usa){const e=extra[best.k]=extra[best.k]||{};e[best.usa]=(e[best.usa]||0)+1}}}
  x.p=p})}
function naPlCard(){const ks=naPlContratos();if(!ks.length)return '';const el=plElegib(NA.semCpf?'':NA.cpf,NA.pac.n),conv=NA.tipo==='convenio';
 const tab=NA.ex.reduce((s,x)=>s+(x.p0??x.p),0),pag=naTotal(),cob=Math.round((tab-pag)*100)/100;
 return `<div class="card at-card" id="naPlano"><h3>Plano e pacote ${info('Elegibilidade calculada na hora: situação do contrato, carência, limite de uso no mês e saldo do pacote. A cobertura entra sozinha no preço de cada item; a recepção não digita desconto de plano.')}</h3><div class="sub">${esc(NA.pac.n.split(' ')[0])} tem ${ks.length>1?ks.length+' contratos':'um contrato'} na DeoVita</div>
 ${el.map(e=>`<div class="alert ${e.s[2]==='ok'?'ok':e.s[2]==='err'?'err':e.s[2]==='warn'?'warn':'info'}"><span><b>${esc(e.ref.n)}</b> · ${e.k.id} · <span class="badge ${e.s[2]}">${e.s[1]}</span>${e.dep?' · dependente de '+esc(e.k.tit):' · titular'}${e.k.empresa?' · '+esc(e.k.empresa):''}<br>${e.msg}</span></div>
  ${e.s[0]==='inadimplente'?`<button class="btn sm sec" style="align-self:flex-start" onclick="naPlMensalidade('${e.k.id}')" ${tipAttr('Receber a mensalidade','Recebe a mensalidade em aberto no seu caixa; o contrato volta a adimplente e o desconto entra no pedido na hora.')}>Receber mensalidade de ${plDm(e.k.mensAbertas[0])} (${fmt(plPlano(e.k.ref).mens)})</button>`:''}`).join('')}
 ${conv?`<p class="tl">Atendimento por convênio: o plano DeoVita não se soma ao convênio; os itens seguem a tabela do convênio.</p>`:NA.ex.length?`<div class="tablewrap"><table class="at-table"><thead><tr><th>Item</th><th>Tabela</th><th>Plano ou pacote</th><th>A pagar</th></tr></thead><tbody>${NA.ex.map(x=>`<tr><td data-l="Item">${esc(EX[x.c].n)}</td><td data-l="Tabela">${fmt(x.p0??x.p)}</td><td data-l="Plano ou pacote">${x.pl?`<span class="${x.pl.via?'prazo-ok':'tl'}">${esc(x.pl.txt)}</span>`:NA.plOff?'<span class="tl">não usado neste atendimento</span>':'<span class="tl">—</span>'}</td><td data-l="A pagar"><b>${fmt(x.p)}</b></td></tr>`).join('')}</tbody></table></div>
 <div class="at-totals"><div><span>Preço de tabela</span><span>${fmt(tab)}</span></div><div><span>Plano e pacote</span><span>${cob?'− '+fmt(cob):fmt(0)}</span></div><div class="at-big"><span>A pagar</span><span>${fmt(pag)}</span></div></div>`:'<p class="tl">Inclua os itens: a cobertura aparece aqui, item a item.</p>'}
 ${!conv?`<label class="check"><input type="checkbox" ${NA.plOff?'checked':''} onchange="naPlOff(this.checked)">Não usar o plano neste atendimento ${info('Ex.: o paciente prefere guardar o saldo do pacote. Fica registrado com quem marcou.')}</label>`:''}
 <a href="#planos" class="tl" onclick="PLN_ABA='contratos'">Ver o contrato em Planos e pacotes</a></div>`}
function naPlOff(v){NA.plOff=v;naRender();toast(v?'Plano desligado neste atendimento: preços de tabela (fica registrado)':'Plano aplicado de novo')}
