(function(){
 const _cad=naCadastro,_p1=naP1,_p2=naP2,_p3=naP3,_ed=naEditItem,_edOk=naEditOk,_conc=naConcluir,_fim=naFim;
 naP1=function(){const h=_p1();return NA.modo==='atendimento'?h.replace('<div class="at-hint"><div>','<div class="at-hint"><div><b>Planos e pacotes:</b> 111.444.777-35 (família, adimplente) · 123.456.789-09 (em carência) · 222.333.444-05 (dependente, titular inadimplente) · 246.357.468-59 (pacote pré-natal) · 555.666.777-80 (check-up) · 987.654.321-00 (plano empresa).</div><div>'):h};
 naCadastro=function(){const h=_cad();if(NA.modo!=='atendimento')return h;const el=plElegib(NA.semCpf?'':NA.cpf,(NA.pac||{}).n);if(!el.length)return h;
  return `<div class="card at-card"><h3>Elegibilidade ${info('Consultada no cadastro único de planos e pacotes, sem segundo banco: o que o paciente pode usar hoje.')}</h3>${el.map(e=>`<div class="alert ${e.s[2]==='ok'?'ok':e.s[2]==='err'?'err':e.s[2]==='warn'?'warn':'info'}"><span><b>${esc(e.ref.n)}</b> · <span class="badge ${e.s[2]}">${e.s[1]}</span>${e.dep?' · dependente de '+esc(e.k.tit):''}<br>${e.msg}</span></div>`).join('')}</div>`+h};
 naP2=function(){naPlRecalc();const h=_p2();const c=naPlCard();return c?h.replace('<div class="card at-card"><h3>Exames e procedimentos</h3>',c+'<div class="card at-card"><h3>Exames e procedimentos</h3>'):h};
 naP3=function(){naPlRecalc();const c=naPlCard();return c+_p3()};
 naEditItem=function(i){const x=NA.ex[i];if(!x||x.p0===undefined)return _ed(i);const net=x.p;x.p=x.p0;_ed(i);x.p=net};
 naEditOk=function(i){const x=NA.ex[i];if(x)delete x.p0;_edOk(i)};
 naConcluir=function(){const usados=NA.modo==='atendimento'&&!NA.fim?NA.ex.filter(x=>x.pl&&x.pl.via).map(x=>({...x})):[];const nome=(NA.pac||{}).n;_conc();
  if(!NA.fim||NA.fim.tipo!=='at'||!usados.length)return;let econ=0;
  usados.forEach(x=>{const k=PL_CONTRATOS.find(c=>c.id===x.pl.k);if(!k)return;k.consumo.unshift({d:PL_HOJE,pac:nome,c:x.c,tab:x.p0,pago:x.p,at:NA.fim.prot,pk:x.pl.via==='pacote'?1:0});if(x.pl.via==='pacote'&&k.saldo[x.c])k.saldo[x.c]--;econ+=x.p0-x.p});
  NA.fim.pl=`${usados.length} ${usados.length>1?'itens usaram':'item usou'} plano ou pacote (${fmt(Math.round(econ*100)/100)} a menos para o paciente). O consumo entrou no histórico do contrato.`;
  if(typeof x2Aud==='function')x2Aud('Planos e pacotes',`Atendimento ${NA.fim.prot}: ${NA.fim.pl}`);naRender(true)};
 naFim=function(){const h=_fim();return NA.fim&&NA.fim.pl?h.replace('<p style="font-size:14px;color:var(--fg2)">Entrega por',`<div class="alert info"><span><b>Plano e pacote:</b> ${NA.fim.pl}</span></div><p style="font-size:14px;color:var(--fg2)">Entrega por`):h};
})();

