function colMarca(c,ok){const el=$('#ce_'+c),b=$('#ceb_'+c);if(!el)return;el.classList.toggle('pend',!ok);b.className='badge '+(ok?'ok':'warn');b.textContent=ok?'colhido':'pendente';if(!ok){const o=$('#ceo_'+c);if(o)o.focus()}}
