function colEtiquetas(){const p=colPac();if(!p){toast('Chame um paciente antes de imprimir as etiquetas','warn');return}const s=colSel();etiquetaPrev({n:p.n,nasc:p.nasc,prot:p.prot,exs:s.ok.length?s.ok:p.exs,modo:'Impressora do box 1',tri:triDe(p.prot),preColeta:true})}
function colRegistrar(){const p=colPac();if(!p){toast('Ninguém no box agora','warn');return}const s=colSel();
 if(!s.ok.length&&!s.pend.length)return;if(s.pend.some(x=>!x.obs)){toast('Escreva a observação de cada exame que ficou pendente','warn');const x=s.pend.find(x=>!x.obs);const o=$('#ceo_'+x.c);if(o)o.focus();return}
 s.pend.forEach(x=>COL_PEND.unshift({prot:p.prot,n:p.n,ex:x.c,mot:x.mot,obs:x.obs,h:hhmm(new Date())}));
 const nome=p.n.split(' ')[0];CHAMADA.col={s:'—',h:hhmm(new Date()),vazio:true};reView();
 retorno(s.pend.length?'erro':'ok',s.pend.length?'Coleta registrada com pendência':'Coleta registrada',`${s.ok.length} exame(s) de ${esc(nome)} em C (colhido) às ${hhmm(new Date())} e seguem para o transporte ou o recebimento.${s.pend.length?` ${s.pend.length} ficou(aram) pendente(s), com motivo e observação: ${s.pend.map(x=>EX[x.c]?EX[x.c].n:x.c).join(', ')}. A recepção e o posto recebem o aviso.`:''}`)}
